<?php
require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();$month=$_GET['month']??date('Y-m');$s=$p->prepare("SELECT COALESCE(SUM(total),0) sales,COALESCE(SUM(cost),0) costs,COALESCE(SUM(profit),0) profit,COUNT(*) qty FROM orders WHERE substr(created_at,1,7)=? AND status<>'Cancelado'");$s->execute([$month]);$sum=$s->fetch();$s=$p->prepare("SELECT oi.product_name,SUM(oi.qty) qty,SUM(oi.qty*oi.unit_price) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE substr(o.created_at,1,7)=? AND o.status<>'Cancelado' GROUP BY oi.product_name ORDER BY qty DESC LIMIT 10");$s->execute([$month]);$top=$s->fetchAll();$s=$p->prepare("SELECT u.name,u.commission_pct,SUM(o.total) sales,COUNT(*) qty FROM orders o LEFT JOIN users u ON u.id=o.seller_id WHERE substr(o.created_at,1,7)=? AND o.status<>'Cancelado' GROUP BY u.id ORDER BY sales DESC");$s->execute([$month]);$salespeople=$s->fetchAll();$repeat=(int)$p->query("SELECT COUNT(*) FROM (SELECT customer_id FROM orders WHERE customer_id IS NOT NULL AND status<>'Cancelado' GROUP BY customer_id HAVING COUNT(*)>1)")->fetchColumn();$avg=(float)$p->query("SELECT COALESCE(AVG(total),0) FROM orders WHERE substr(created_at,1,7)='$month' AND status<>'Cancelado'")->fetchColumn();$loss=(float)$p->query("SELECT COALESCE(SUM(cost),0) FROM losses WHERE substr(loss_date,1,7)='$month'")->fetchColumn();page_head('Relatórios');?>
<div class="card"><form><label>Mês</label><input style="max-width:220px" type="month" name="month" value="<?=e($month)?>" onchange="this.form.submit()"></form></div><div class="grid g4"><div class="card kpi"><span>Faturamento</span><strong><?=money($sum['sales'])?></strong></div><div class="card kpi"><span>Lucro bruto</span><strong><?=money($sum['profit'])?></strong></div><div class="card kpi"><span>Perdas</span><strong><?=money($loss)?></strong></div><div class="card kpi"><span>Pedidos</span><strong><?=$sum['qty']?></strong></div></div><div class="grid g2"><div class="card kpi"><span>Ticket médio</span><strong><?=money($avg)?></strong></div><div class="card kpi"><span>Clientes recorrentes</span><strong><?=$repeat?></strong></div></div>
<div class="grid g2"><div class="card"><h2>Produtos mais vendidos</h2><div class="table"><table><tr><th>Produto</th><th>Qtd.</th><th>Receita</th></tr><?php foreach($top as $x):?><tr><td><?=e($x['product_name'])?></td><td><?=$x['qty']?></td><td><?=money($x['revenue'])?></td></tr><?php endforeach;?></table></div></div><div class="card"><h2>Vendedores / comissão</h2><div class="table"><table><tr><th>Vendedor</th><th>Vendas</th><th>Faturamento</th><th>Comissão</th></tr><?php foreach($salespeople as $x):?><tr><td><?=e($x['name']?:'Sem vendedor')?></td><td><?=$x['qty']?></td><td><?=money($x['sales'])?></td><td><?=money($x['sales']*$x['commission_pct']/100)?></td></tr><?php endforeach;?></table></div></div></div><?php page_foot();?>